	for instance, bosses in pairs(added) do
		local known = addon.LootTable[instance]
		if not known then
			addon.LootTable[instance] = bosses
		else
			for boss, items in pairs(bosses) do
				local list = known[boss]
				if not list then
					known[boss] = items
				else
					-- an encounter this expansion added drops to, on top of what it already had
					for _, itemID in ipairs(items) do list[#list + 1] = itemID end
				end
			end
		end
	end
